attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){ float u = (uTime - aT)/1.250; if (u < 0. || u > 1.750){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK;
      if (aK < .5){ float S = 5.000; vP = position.xy*S; gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(vP.x, .03, -vP.y), 1.); return; }
      vec4 mv = viewMatrix*vec4(aO + vec3(0., 1.3, 0.), 1.);                         /* the eclipse emblem, small billboard over the centre */
      float k = clamp(u/0.600, 0., 1.), S = .9*(1. - pow(1. - k, 3.))*(1. + .15*step(1.000, u)*exp(-(u - 1.000)*8.));   /* slow pop-in, together with the circle; holds until the flash */
      mv.xy += position.xy*S; vP = position.xy; gl_Position = projectionMatrix*mv; }

